    import re

text_spaces = re.findall(r'\s+|\S+', text)
space_groups = [len(item) for item in text_spaces if item.isspace()]

if not space_groups:
    return text

mean = sum(space_groups) / len(space_groups)
mad = sum(abs(s - mean) for s in space_groups) / len(space_groups)

result_parts = []
for item in text_spaces:
    if item.isspace():
        count = len(item)
        deviation = abs(count - mean)
        if deviation > mad:
            if count > 2:
                replacement = "="
            else:
                replacement = "*" * count
        else:
            if count > 2:
                replacement = "-"
            else:
                replacement = "_" * count
        result_parts.append(replacement)
    else:
        result_parts.append(item)

return "".join(result_parts)
